 "content": "def transform(grid):
    """Move each 4 down one cell; a 4 resting above the 2-barrier emits a V."""
    h, w = len(grid), len(grid[0])
    barrier = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    out = [[0 if value == 4 else value for value in row] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            nr = r + 1 if r + 1 < h else r
            # The horizontal 2 row is an obstruction; a 4 immediately above
            # it stays in place. Otherwise the 4 falls by one cell.
            if barrier is not None and r < barrier and nr >= barrier:
                nr = r
            out[nr][c] = 4

            # A 4 one cell above the barrier fans upward along both diagonals.
            if barrier is not None and nr == barrier - 1:
                for distance in range(1, barrier):
                    rr = nr - distance
                    if rr < 0:
                        break
                    left, right = c - distance, c + distance
                    if 0 <= left < w:
                        out[rr][left] = 4
                    if 0 <= right < w:
                        out[rr][right] = 4

    return out
